def flaky(n):
    state = {"calls": 0}
    def fn():
        state["calls"] += 1
        if state["calls"] <= n:
            raise RuntimeError("fail")
    return fn

def with_retries(fn, retries):
    attempts = 0
    for _ in range(retries + 1):
        attempts += 1
        try:
            fn()
            return (True, attempts)
        except Exception:
            pass
    return (False, attempts)

print(with_retries(flaky(2), 2))
print(with_retries(flaky(2), 1))
print(with_retries(flaky(0), 0))

